// ── STEP 1: Normalize input ────────────────────────────────────────
// Workflow 1 sends { items: [...] } as a single payload
const payload = $input.first().json;
let rawItems = [];

if (Array.isArray(payload.items)) {
  rawItems = payload.items;
} else if (Array.isArray(payload)) {
  rawItems = payload;
} else {
  throw new Error('No items received from Workflow 1. Payload: ' + JSON.stringify(payload));
}

if (rawItems.length === 0) {
  throw new Error('Workflow 2 received an empty items array.');
}

// Cast types and return one item per row
return rawItems.map(item => ({
  json: {
    icode                : Number(item.icode),
    item_name            : String(item.item_name ?? `Item ${item.icode}`),
    required_to_reach_min: Number(item.required_to_reach_min ?? 0),
    uom                  : String(item.uom ?? 'PCS'),
    sono                 : item.sono ?? null,
    soid                 : item.soid ?? null
  }
}));

// ── STEP 2: Merge item metadata + vendor response ──────────────────
// At this point each item flowing in IS the vendor API response.
// We re-fetch the original item from Normalize Input Items using
// the same index position — no pairedItem needed.

const vendorResponses = $input.all();
const originalItems   = $('Normalize Input Items').all();

// Build vendor map grouped by vendor_code
const vendorMap = {};

for (let i = 0; i < vendorResponses.length; i++) {
  const vendorResp = vendorResponses[i].json;
  const origItem   = originalItems[i]?.json;

  if (!origItem) continue;

  // Handle both response shapes: flat array OR { vendors: [] }
  let vendors = [];
  if (Array.isArray(vendorResp)) {
    vendors = vendorResp;
  } else if (Array.isArray(vendorResp?.vendors)) {
    vendors = vendorResp.vendors;
  } else if (Array.isArray(vendorResp?.data)) {
    vendors = vendorResp.data;
  }
  // If still empty, this item has no vendors — skip silently
  if (vendors.length === 0) continue;

  for (const v of vendors) {
    const vendor_code  = (v.chcode ?? '').trim();
    const phone_number = (v.mobile ?? v.phone ?? '').trim();

    if (!vendor_code)  continue;  // must have vendor_code
    if (!phone_number) continue;  // must have phone for WhatsApp

    if (!vendorMap[vendor_code]) {
      vendorMap[vendor_code] = {
        vendor_code,
        vendor_name   : String(v.name ?? vendor_code),
        phone_number  : String(phone_number),
        contact_person: v.contact_person ?? null,
        items         : [],
        _seen         : new Set()
      };
    }

    // Dedupe: one row per vendor+icode combo
    const dedupeKey = `${vendor_code}|${origItem.icode}`;
    if (vendorMap[vendor_code]._seen.has(dedupeKey)) continue;
    vendorMap[vendor_code]._seen.add(dedupeKey);

    vendorMap[vendor_code].items.push({
      icode        : origItem.icode,
      item_name    : origItem.item_name,
      required_qty : origItem.required_to_reach_min,
      uom          : origItem.uom,
      sono         : origItem.sono,
      soid         : origItem.soid,
      vendor_code
    });
  }
}

const result = Object.values(vendorMap).map(v => {
  delete v._seen;
  return { json: v };
});

if (result.length === 0) {
  throw new Error('No vendors with valid phone numbers found for any item.');
}

return result;

// ── STEP 3: Build demand items (unique by icode) + store vendor list
// We need one demand POST with all unique items.
// Vendor list is stored here and passed forward.

const vendors = $input.all().map(i => i.json);

const seenIcodes  = new Set();
const demandItems = [];

for (const vendor of vendors) {
  for (const item of vendor.items) {
    if (!seenIcodes.has(item.icode)) {
      seenIcodes.add(item.icode);
      demandItems.push({
        icode        : item.icode,
        item_name    : item.item_name,
        required_qty : item.required_qty,
        uom          : item.uom
      });
    }
  }
}

return [{
  json: {
    demand_items: demandItems,
    vendors
  }
}];

// ── STEP 4: Validate demand_id, attach to each vendor as separate items
const erpResp   = $input.first().json;
const demand_id = erpResp.demand_id ?? erpResp.id ?? null;

if (!demand_id) {
  throw new Error('Demand creation failed — no demand_id in response: ' + JSON.stringify(erpResp));
}

// Pull vendor list from Prepare Demand Payload node
const vendors = $('Prepare Demand Payload').first().json.vendors;

// Return one item per vendor, each carrying the demand_id
return vendors.map(vendor => ({
  json: {
    demand_id,
    vendor_code   : vendor.vendor_code,
    vendor_name   : vendor.vendor_name,
    phone_number  : vendor.phone_number,
    contact_person: vendor.contact_person,
    items         : vendor.items
  }
}));

// ── STEP 5: Chunk vendor items into groups of 8 for WhatsApp
const CHUNK_SIZE = 8;
const vendor = $input.item.json;

const chunks = [];
for (let i = 0; i < vendor.items.length; i += CHUNK_SIZE) {
  const slice = vendor.items.slice(i, i + CHUNK_SIZE);
  const lines = slice.map(item => {
    const qty  = Number(item.required_qty) || 0;
    const qStr = qty > 0 ? `${qty.toFixed(1)} ${item.uom || 'PCS'}` : '-';
    const name = item.item_name
      .replace(/\\/g, '')
      .replace(/"/g,  "''")
      .replace(/[\x00-\x1F\x7F]/g, '')
      .trim();
    return `*➤ (icode=${item.icode})* | ${name} | _*Qty:*_ _${qStr}_`;
  });
  chunks.push({ items: slice, items_text: lines });
}

// Return the full vendor with chunks embedded — still one item per vendor
return [{
  json: {
    demand_id    : vendor.demand_id,
    vendor_code  : vendor.vendor_code,
    vendor_name  : vendor.vendor_name,
    phone_number : vendor.phone_number,
    items        : vendor.items,
    chunks
  }
}];

// ── STEP 6: Expand chunks into individual messages
// One output row per chunk so sub-template sends each chunk separately
const vendor = $('Loop Over Vendors').item.json;

return vendor.chunks.map((chunk, idx) => {
  const itemsText = chunk.items_text
    .map(t => t.replace(/[*_]/g, '').trim())
    .join(' | ');

  return {
    json: {
      phone_number : vendor.phone_number,
      vendor_code  : vendor.vendor_code,
      vendor_name  : vendor.vendor_name,
      demand_id    : vendor.demand_id,
      list_number  : String(idx + 1),
      items_text   : itemsText,
      chunk_items  : chunk.items
    }
  };
});

// ── STEP 7: Expand chunk_items into individual rows for ERP quotation
// Each item in the chunk needs its own quotation record
const chunk = $input.item.json;

return chunk.chunk_items.map((item, idx) => ({
  json: {
    icode        : item.icode,
    item_name    : item.item_name,
    required_qty : item.required_qty,
    uom          : item.uom,
    sono         : item.sono ?? null,
    soid         : item.soid ?? null,
    vendor_code  : chunk.vendor_code,
    vendor_name  : chunk.vendor_name,
    phone_number : chunk.phone_number,
    demand_id    : chunk.demand_id
  },
  pairedItem: { item: idx }
}));

// After merge, restore full item context from Expand Items For Quotation
// merge output keeps input0 data (Mark Msg Sent ERP response)
// We need to re-attach vendor_code, demand_id etc from the expand node
// Both branches had same index items so we use position matching

const mergedItems = $input.all();
const expandedItems = $('Expand Items For Quotation').all();

return mergedItems.map((item, idx) => {
  const ctx = expandedItems[idx]?.json ?? {};
  return {
    json: {
      icode        : ctx.icode,
      item_name    : ctx.item_name,
      required_qty : ctx.required_qty,
      uom          : ctx.uom,
      sono         : ctx.sono ?? null,
      soid         : ctx.soid ?? null,
      vendor_code  : ctx.vendor_code,
      vendor_name  : ctx.vendor_name,
      phone_number : ctx.phone_number,
      demand_id    : ctx.demand_id
    }
  };
});

// ── STEP 8: Validate ERP response, attach quotation_id to item context
const erpResp       = $input.item.json;
const quotation_id  = erpResp.quotation_id ?? null;
const quotation_number = erpResp.quotation_number ?? null;

if (!quotation_id) {
  throw new Error(
    `ERP quotation creation failed for vendor ${$('Restore Item Context After Merge').item.json.vendor_code}: ` +
    JSON.stringify(erpResp)
  );
}

// Recover item context — input is the ERP response, use index matching
const ctx = $('Restore Item Context After Merge').item.json;

return [{
  json: {
    quotation_id,
    quotation_number,
    icode         : ctx.icode,
    vendor_code   : ctx.vendor_code,
    vendor_name   : ctx.vendor_name,
    vendor_contact: ctx.phone_number,
    qty           : ctx.required_qty,
    soid          : ctx.soid ?? null,
    sono          : ctx.sono ?? null,
    demand_id     : ctx.demand_id
  }
}];

// Re-attach quotation context for SOID update
// Both merge inputs had same items — use Attach Quotation ID as source of truth
const ctx = $('Attach Quotation ID').item.json;
return [{
  json: {
    quotation_id: ctx.quotation_id,
    soid        : ctx.soid ?? null
  }
}];
